            C++

    #include <bits/stdc++.h>
using namespace std;

// Check if x is a perfect square
bool isPerfectSquare(int x)
{
    int s = sqrt(x);

    return s * s == x;
}

// Check if n is a Fibonacci number
bool isFibonacci(int n)
{
    int val1 = 5 * n * n + 4;
    int val2 = 5 * n * n - 4;

    return isPerfectSquare(val1) || isPerfectSquare(val2);
}

int main()
{
    int n = 34;

    if (isFibonacci(n))
        cout << "true";
    else
        cout << "false";

    return 0;
}


